// PASO 1: Definir los productos y sus precios.
const products = [{
  name: 'Sound Pro',
  type: 'Audio',
  price: 249,
  mark: 'S / 01',
  desc: 'Audífonos con cancelación de ruido.'
}, {
  name: 'Keys Mini',
  type: 'Accesorios',
  price: 189,
  mark: 'K / 02',
  desc: 'Teclado compacto para tu escritorio.'
}, {
  name: 'Pulse Speaker',
  type: 'Audio',
  price: 159,
  mark: 'P / 03',
  desc: 'Parlante portátil con sonido envolvente.'
}, {
  name: 'Hub Connect',
  type: 'Accesorios',
  price: 129,
  mark: 'H / 04',
  desc: 'Conecta tus accesorios con un hub USB-C.'
}, {
  name: 'Studio Mic',
  type: 'Audio',
  price: 219,
  mark: 'M / 05',
  desc: 'Micrófono USB para llamadas y grabación.'
}, {
  name: 'Charge Duo',
  type: 'Accesorios',
  price: 99,
  mark: 'C / 06',
  desc: 'Base de carga para un escritorio ordenado.'
}]; // PASO 2: Guardar la selección del usuario en memoria.
let cart = [];
const money = n => 'S/ ' + n.toFixed(2); // PASO 3: Dibujar las tarjetas según la categoría elegida.
function render(filter = 'Todos') {
  document.querySelector('#products').innerHTML = products.map((p, i) => ({
    ...p,
    i
  })).filter(p => filter === 'Todos' || p.type === filter).map(p => `<article class="card"><span class="tag">${p.type}</span><div class="product-mark" aria-hidden="true">${p.mark}</div><h3>${p.name}</h3><p>${p.desc}</p><p class="price">${money(p.price)}</p><button data-add="${p.i}">Agregar al carrito</button></article>`).join('');
} // PASO 4: Detectar el botón Agregar y actualizar el carrito.
document.querySelector('#products').addEventListener('click', e => {
  const b = e.target.closest('[data-add]');
  if (!b) return;
  cart.push(Number(b.dataset.add));
  document.querySelector('#count').textContent = cart.length;
  b.textContent = 'Agregado ✓';
}); // PASO 5: Cambiar el filtro y volver a dibujar el catálogo.
document.querySelector('#filters').addEventListener('click', e => {
  const b = e.target.closest('[data-filter]');
  if (!b) return;
  document.querySelectorAll('[data-filter]').forEach(x => x.setAttribute('aria-pressed', x === b));
  render(b.dataset.filter);
}); // PASO 6: Mostrar cantidades, botones para quitar y total.
function showCart() {
  document.querySelector('#items').innerHTML = cart.length ? products.map((p, i) => ({
    p,
    i,
    qty: cart.filter(x => x === i).length
  })).filter(x => x.qty).map(x => `<div class="row"><span>${x.p.name} × ${x.qty}</span><button data-remove="${x.i}" aria-label="Quitar un ${x.p.name}">Quitar</button></div>`).join('') : '<p>Tu carrito está vacío.</p>';
  document.querySelector('#total').textContent = 'Total: ' + money(cart.reduce((s, i) => s + products[i].price, 0));
  document.querySelector('#count').textContent = cart.length;
} // PASO 7: Abrir, cerrar y vaciar la ventana del carrito.
const dialog = document.querySelector('#basket');
document.querySelector('#cart').onclick = () => {
  showCart();
  dialog.showModal();
};
document.querySelector('#close').onclick = () => dialog.close();
document.querySelector('#clear').onclick = () => {
  cart = [];
  showCart();
};
document.querySelector('#items').onclick = e => {
  const b = e.target.closest('[data-remove]');
  if (b) {
    cart.splice(cart.indexOf(Number(b.dataset.remove)), 1);
    showCart();
  }
};
render();
